    {
      "claim": "AI-powered toys with companion chatbots should be prohibited because they exploit a documented vulnerability in child development that existing law cannot address.",
      "targets": [],
      "relationship": "main thesis"
    },
    {
      "claim": "Under current Section 230 jurisprudence, platforms are not liable for user-generated content, but AI-generated content is not user-generated, creating an accountability vacuum.",
      "targets": [],
      "relationship": "structural liability gap"
    },
    {
      "claim": "A 2022 study in JAMA Pediatrics found that children who formed strong emotional attachments to conversational AI showed increased social withdrawal and decreased willingness to seek help from human caregivers.",
      "targets": [],
      "relationship": "empirical evidence of harm"
    },
    {
      "claim": "The Consumer Product Safety Commission recalled 3.2 million children's products in 2022 for design defects that had passed existing safety standards, demonstrating that pre-market certification is insufficient for generative AI toys.",
      "targets": [],
      "relationship": "precedent for regulatory insufficiency"
    },
    {
      "claim": "A ban with a sunset clause until 2031, conditioned on demonstrable safety mechanisms and enforceable liability, forces the industry to solve the accountability problem before marketing to children.",
      "targets": [],
      "relationship": "proportional policy response"
    }
